window.AUTH=window.AUTH||{};window.AUTH["16-1275"]={"d":"16-1275","id":"2018/16-1275","n":"Virginia Uranium, Inc. v. Warren","briefs":[{"k":"petitioner","label":"Brief of petitioner Virginia Uranium, Inc., et al.","date":"2018-07-19","url":"https://www.supremecourt.gov/DocketPDF/16/16-1275/54817/20180719144052589_Petitioners%20Brief.pdf","side":"pet","n":29},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-07-26","url":"https://www.supremecourt.gov/DocketPDF/16/16-1275/55605/20180726155641352_16-1275tsacUnitedStates.pdf","side":"us","n":55},{"k":"respondent","label":"Brief of respondents John Warren, et al.","date":"2018-08-27","url":"https://www.supremecourt.gov/DocketPDF/16/16-1275/60812/20180827152000329_Va%20Uranium%20v%20Warren%20Respondents%20Merits%20Brief.pdf","side":"res","n":75},{"k":"reply","label":"Reply of petitioners Virginia Uranium, Inc., et al.","date":"2018-09-26","url":"https://www.supremecourt.gov/DocketPDF/16/16-1275/64883/20180926121155868_Virginia%20Uranium%20Reply%20Brief.pdf","side":"pet","n":21}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/16-1275_7lho.pdf","tr":true,"items":[{"t":"case","label":"Abraham v. Hodges","cite":"255 F. Supp. 2d 539","y":2002,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/255/539/","by":{"0":"50"}},{"t":"case","label":"Arizona v. United States","cite":"132 S. Ct. 2492","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"57","2":"51"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"County of Suffolk v. Long Island Lighting Co.","cite":"728 F.2d 52","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/728/52/","by":{"0":"52"}},{"t":"case","label":"CSX Transp., Inc. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","3":"12"}},{"t":"case","label":"Edgar v. MITE Corp.","cite":"457 U.S. 624","y":1982,"id":"1981/80-1188","sc":1,"sum":"With regard to the Commerce Clause. The Illinois Act imposes burdens on interstate commerce that are excessive in light of the local interests the Act purports to further. Among the ways a corporation can be covered by the Act is if 10% of the class of equity securities subject to the offer is owned by shareholders located in Illinois.","sumSrc":"Oyez","by":{"0":"28, 55"}},{"t":"case","label":"English v. General Elec. Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"op":7,"ar":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"1, 12, 14, 16"}},{"t":"case","label":"Entergy Nuclear Vermont Yankee, LLC v. Shumlin","cite":"733 F.3d 393","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/733/393/","op":1,"ar":3,"by":{"0":"2, 23, 50, 51, 52","1":"33","3":"18, 22"}},{"t":"case","label":"Gade v. National Solid Wastes Mgmt. Ass’n","cite":"505 U.S. 88","y":1992,"id":"1991/90-1676","sc":1,"op":1,"sum":"The judgment is affirmed. 918 F. 2d 671, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 58","1":"34","3":"7, 8, 24"}},{"t":"case","label":"Hernandez v. Mesa","cite":"137 S. Ct. 2003","y":2017,"id":"2016/15-118","sc":1,"sum":"The Court determined that qualified immunity may not be granted based on facts that were unknown to the officer at the time of the incident, and that a court should consider whether an implied right of action is appropriate under Bivens v. Six Unknown Federal Narcotics Agents before addressing sensitive Fourth Amendment questions.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"op":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Huffman v. Western Nuclear, Inc.","cite":"486 U.S. 663","y":1988,"id":"1987/87-645","sc":1,"op":1,"sum":"Section 161(v) does not require DOE to restrict the enrichment of foreign uranium where such restriction would not achieve the statutory goal of \"assur[ing] the maintenance of a viable domestic uranium industry,\" for the statute ties the amount of restriction to be imposed to the achievement of that goal. Pp. 671-674. 825 F. 2d 1430, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11","1":"3","2":"5"}},{"t":"case","label":"Illinois v. General Electric Co.","cite":"683 F.2d 206","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/206/","by":{"0":"49"}},{"t":"case","label":"Jersey Cent. Power & Light Co. v. Lacey Twp.","cite":"772 F.2d 1103","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/772/1103/","by":{"0":"50"}},{"t":"case","label":"Liverpool & G.W. Steam Co. v. Phenix Ins. Co.","cite":"129 U.S. 397","y":1889,"id":"scdb/1888-123","sc":1,"sum":"A decree of tlie Circuit Court in admiralty on the instance side, finding negligence in the stranding of a ship, can be reviewed by this court so far only as it involves a question of law.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Northern States Power Co. v. Minnesota","cite":"447 F.2d 1143","y":1971,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/447/1143/","by":{"0":"34, 52"}},{"t":"case","label":"Northern States Power Co. v. Prairie Island Mdewakanton Sioux Indian Community","cite":"781 F. Supp. 612","y":1991,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp./781/612/","by":{"0":"52"}},{"t":"case","label":"Pacific Gas & Elec. Co. v. State Energy Res. Conservation & Dev. Comm’n","cite":"461 U.S. 190","y":1983,"id":"1982/81-1945","sc":1,"op":12,"sum":"The Court held that the California law did not impinge upon congressional authority. The Court found that because the rationale for enacting the law was an economic one, it did not interfere with federal regulations governing nuclear safety.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Rice v. Santa Fe Elevator Corp.","cite":"331 U.S. 218","y":1947,"id":"scdb/1946-098","sc":1,"sum":"1. By the 1931 amendments to §§ 6 and 29 of the United States Warehouse Act, Congress terminated the dual system of regulation provided by the original Act and substituted an exclusive system of federal regulation of warehouses licensed under the Federal Act with reference to the subjects covered thereby, except to the extent that express exceptions in the Federal Act subject certain phases of the business to state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Silkwood v. Kerr-McGee Corp.","cite":"464 U.S. 238","y":1984,"id":"1983/81-2159","sc":1,"op":1,"sum":"Appellant's decedent, a laboratory analyst at a federally licensed nuclear plant in Oklahoma operated by appellee Kerr-McGee Nuclear Corp. (hereafter appellee), was contaminated by plutonium. Subsequently, after the decedent was killed in an unrelated automobile accident, appellant, as administrator of the decedent's estate, brought a diversity action in Federal District Court based on common-law tort principles …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 11, 39, 55, 58","1":"18","2":"8, 35, 36","3":"14"}},{"t":"case","label":"Skull Valley Band of Goshute Indians v. Nielson","cite":"376 F.3d 1223","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1223/","op":5,"ar":6,"by":{"0":"passim","1":"27, 28, 33","3":"18, 19"}},{"t":"case","label":"United States v. Kentucky","cite":"252 F.3d 816","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/816/","by":{"0":"49, 50"}},{"t":"case","label":"United States v. Manning","cite":"527 F.3d 828","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/527/828/","by":{"0":"50"}},{"t":"const","label":"Article VI, Section 2","by":{"0":"30"}},{"t":"usc","label":"42 U.S.C. § 2011","url":"https://www.law.cornell.edu/uscode/text/42/2011","stext":{"head":"§2011. Congressional declaration of policy","paras":[[0,"Atomic energy is capable of application for peaceful as well as military purposes. It is therefore declared to be the policy of the United States that—"],[1,"(a) the development, use, and control of atomic energy shall be directed so as to make the maximum contribution to the general welfare, subject at all times to the paramount objective of making the maximum contribution to the common defense and security; and"],[1,"(b) the development, use, and control of atomic energy shall be directed so as to promote world peace, improve the general welfare, increase the standard of living, and strengthen free competition in private enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2011?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2011. Congressional declaration of policy","tname":"The Public Health and Welfare","by":{"0":"54","1":"1, 2","2":"1"}},{"t":"usc","label":"42 U.S.C. § 2021","url":"https://www.law.cornell.edu/uscode/text/42/2021","subs":["(a)(1)","(b)","(c)","(c)(1)","(d)(1)","(k)","(l)","(o)(2)","(a)(4)","(c)(4)","(j)","(o)"],"stext":{"head":"§2021. Cooperation with States","paras":[[0,"(a) Purpose"],[0,"It is the purpose of this section—"],[1,"(1) to recognize the interests of the States in the peaceful uses of atomic energy, and to clarify the respective responsibilities under this chapter of the States and the Commission with respect to the regulation of byproduct, source, and special nuclear materials;"],[1,"(2) to recognize the need, and establish programs for, cooperation between the States and the Commission with respect to control of radiation hazards associated with use of such materials;"],[1,"(3) to promote an orderly regulatory pattern between the Commission and State governments with respect to nuclear development and use and regulation of byproduct, source, and special nuclear materials;"],[1,"(4) to establish procedures and criteria for discontinuance of certain of the Commission's regulatory responsibilities with respect to byproduct, source, and special nuclear materials, and the assumption thereof by the States;"],[1,"(5) to provide for coordination of the development of radiation standards for the guidance of Federal agencies and cooperation with the States; and"],[1,"(6) to recognize that, as the States improve their capabilities to regulate effectively such materials, additional legislation may be desirable."],[0,"(b) Agreements with States"],[0,"Except as provided in subsection (c), the Commission is authorized to enter into agreements with the Governor of any State providing for discontinuance of the regulatory authority of the Commission under subchapters V, VI, and VII of this division, and section 2201 of this title, with respect to any one or more of the following materials within the State:"],[1,"(1) Byproduct materials (as defined in section 2014(e) of this title)."],[1,"(2) Source materials."],[1,"(3) Special nuclear materials in quantities not sufficient to form a critical mass."],[0,"During the duration of such an agreement it is recognized that the State shall have authority to regulate the materials covered by the agreement for the protection of the public health and safety from radiation hazards."],[0,"(c) Commission regulation of certain activities"],[0,"No agreement entered into pursuant to subsection (b) shall provide for discontinuance of any authority and the Commission shall retain authority and responsibility with respect to regulation of—"],[1,"(1) the construction and operation of any production or utilization facility or any uranium enrichment facility;"],[1,"(2) the export from or import into the United States of byproduct, source, or special nuclear material, or of any production or utilization facility;"],[1,"(3) the disposal into the ocean or sea of byproduct, source, or special nuclear waste materials as defined in regulations or orders of the Commission;"],[1,"(4) the disposal of such other byproduct, source, or special nuclear material as the Commission determines by regulation or order should, because of the hazards or potential hazards thereof, not be so disposed of without a license from the Commission."],[0,"The Commission shall also retain authority under any such agreement to make a determination that all applicable standards and requirements have been met prior to termination of a license for byproduct material, as defined in section 2014(e)(2) of this title. Notwithstanding any agreement between the Commission and any State pursuant to subsection (b), the Commission is authorized by rule, regulation, or order to require that the manufacturer, processor, or producer of any equipment, device, commodity, or other product containing source, byproduct, or special nuclear material shall not transfer possession or control of such product except pursuant to a license issued by the Commission."],[0,"(d) Conditions"],[0,"The Commission shall enter into an agreement under subsection (b) of this section with any State if—"],[1,"(1) The 1 Governor of that State certifies that the State has a program for the control of radiation hazards adequate to protect the public health and safety with respect to the materials within the State covered by the proposed agreement, and that the State desires to assume regulatory responsibility for such materials; and"],[1,"(2) the Commission finds that the State program is in accordance with the requirements of subsection (o) and in all other respects compatible with the Commission's program for the regulation of such materials, and that the State program is adequate to protect the public health and safety with respect to the materials covered by the proposed agreement."],[0,"(e) Publication in Federal Register; comment of interested persons"],[0,"(1) Before any agreement under subsection (b) is signed by the Commission, the terms of the proposed agreement and of proposed exemptions pursuant to subsection (f) shall be published once each week for four consecutive weeks in the Federal Register; and such opportunity for comment by interested persons on the proposed agreement and exemptions shall be allowed as the Commission determines by regulation or order to be appropriate."],[0,"(2) Each proposed agreement shall include the proposed effective date of such proposed agreement or exemptions. The agreement and exemptions shall be published in the Federal Register within thirty days after signature by the Commission and the Governor."],[0,"(f) Exemptions"],[0,"The Commission is authorized and directed, by regulation or order, to grant such exemptions from the licensing requirements contained in subchapters V, VI, and VII, and from its regulations applicable to licensees as the Commission finds necessary or appropriate to carry out any agreement entered into pursuant to subsection (b) of this section."],[0,"(g) Compatible radiation standards"],[0,"The Commission is authorized and directed to cooperate with the States in the formulation of standards for protection against hazards of radiation to assure that State and Commission programs for protection against hazards of radiation will be coordinated and compatible."],[0,"(h) Consultative, advisory, and miscellaneous functions of Administrator of Environmental Protection Agency"],[0,"The Administrator of the Environmental Protection Agency shall consult qualified scientists and experts in radiation matters, including the President of the National Academy of Sciences, the Chairman of the National Committee on Radiation Protection and Measurement, and qualified experts in the field of biology and medicine and in the field of health physics. The Special Assistant to the President for Science and Technology, or his designee, is authorized to attend meetings with, participate in the deliberations of, and to advise the Administrator. The Administrator shall advise the President with respect to radiation matters, directly or indirectly affecting health, including guidance for all Federal agencies in the formulation of radiation standards and in the establishment and execution of programs of cooperation with States. The Administrator shall also perform such other functions as the President may assign to him by Executive order."],[0,"(i) Inspections and other functions; training and other assistance"],[0,"The Commission in carrying out its licensing and regulatory responsibilities under this chapter is authorized to enter into agreements with any State, or group of States, to perform inspections or other functions on a cooperative basis as the Commission deems appropriate. The Commission is also authorized to provide training, with or without charge, to employees of, and such other assistance to, any State or political subdivision thereof or group of States as the Commission deems appropriate. Any such provision or assistance by the Commission shall take into account the additional expenses that may be incurred by a State as a consequence of the State's entering into an agreement with the Commission pursuant to subsection (b)."],[0,"(j) Reserve power to terminate or suspend agreements; emergency situations; State nonaction on causes of danger; authority exercisable only during emergency and commensurate with danger"],[0,"(1) The Commission, upon its own initiative after reasonable notice and opportunity for hearing to the State with which an agreement under subsection (b) has become effective, or upon request of the Governor of such State, may terminate or suspend all or part of its agreement with the State and reassert the licensing and regulatory authority vested in it under this chapter, if the Commission finds that (1) such termination or suspension is required to protect the public health and safety, or (2) the State has not complied with one or more of the requirements of this section. The Commission shall periodically review such agreements and actions taken by the States under the agreements to ensure compliance with the provisions of this section."],[0,"(2) The Commission, upon its own motion or upon request of the Governor of any State, may, after notifying the Governor, temporarily suspend all or part of its agreement with the State without notice or hearing if, in the judgment of the Commission:"],[1,"(A) an emergency situation exists with respect to any material covered by such an agreement creating danger which requires immediate action to protect the health or safety of persons either within or outside the State, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2021?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§2021. Cooperation with States","tname":"The Public Health and Welfare","by":{"0":"14","1":"passim, 6, 16, 6, 7, 16, 7, 33, 19, 24, 6, passim, 7, 33, 32","2":"passim, 23, 23, 25, 26, 33, 8, 26, passim, 26"}},{"t":"reg","label":"10 C.F.R. pt. 40","url":"https://www.ecfr.gov/current/title-10/part-40","by":{"0":"13, 14"}},{"t":"reg","label":"Final List of Critical Minerals 2018, 83 Fed. Reg. 23,295","url":"https://www.govinfo.gov/link/fr/83/23295","by":{"0":"8, 54"}},{"t":"case","label":"American Trucking Ass’ns v. City of Los Angeles","cite":"569 U.S. 641","y":2013,"id":"2012/11-798","sc":1,"sum":"The Court held that when a municipal government is acting as a contract-based participant in the market, as opposed to a market regulator, it could not regulate motor carrier activities.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Duke Power Co. v. Carolina Envtl. Study Grp., Inc.","cite":"438 U.S. 59","y":1978,"id":"1977/77-262","sc":1,"sum":"The Price-Anderson Act (Act), having the dual purpose of protecting the public and encouraging the development of the nuclear energy industry, imposes a $560 million limitation on liability for nuclear accidents resulting from the operation of federally licensed private nuclear power plants, requires those indemnified by the $560 million fund established under the Act to waive all legal defenses in the event of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2","2":"6, 7, 29"}},{"t":"case","label":"Engine Mfrs. Ass’n v. South Coast Air Quality Mgmt. Dist.","cite":"541 U.S. 246","y":2004,"id":"2003/02-1343","sc":1,"op":1,"sum":"Stating that it “would make no sense” to allow a state regulation to evade preemption simply because it addressed the purchase, rather than manufacture, of a federally regulated product.","sumSrc":"opinion","by":{"1":"29","2":"37"}},{"t":"case","label":"National Meat Ass’n v. Harris","cite":"565 U.S. 452","y":2012,"id":"2011/10-224","sc":1,"op":14,"ar":4,"sum":"The Court held that a California law requiring slaughterhouses to \"immediately euthanize\" any nonambulatory animal on its premises is preempted by the Federal Meat Inspection Act.","sumSrc":"Oyez","by":{"1":"29","2":"37"}},{"t":"case","label":"Rowe v. New Hampshire Motor Transp. Ass’n","cite":"552 U.S. 364","y":2008,"id":"2007/06-457","sc":1,"sum":"The Court affirmed both lower courts, holding that the FAAAA preempted the state laws. In a unanimous decision written by Justice Stephen Breyer, the Court asserted that the state laws were directly connected with motor carrier services and therefore had a significant and adverse impact on the congressional goal of precluding state regulation in lieu of competitive market forces.","sumSrc":"Oyez","by":{"1":"30","2":"38"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"14","2":"19"}},{"t":"law","label":"Pub. L. No. 86-373","url":"https://www.govinfo.gov/link/statute/73/688","by":{"1":"6","2":"7"}},{"t":"law","label":"Pub. L. No. 89-135","url":"https://www.govinfo.gov/link/statute/79/551","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 2111","url":"https://www.law.cornell.edu/uscode/text/42/2111","by":{"1":"4, 6, 4"}},{"t":"usc","label":"42 U.S.C. § 2012","url":"https://www.law.cornell.edu/uscode/text/42/2012","subs":["(d)"],"stext":{"head":"§2012. Congressional findings","paras":[[0,"The Congress of the United States makes the following findings concerning the development, use, and control of atomic energy:"],[0,"(a) The development, utilization, and control of atomic energy for military and for all other purposes are vital to the common defense and security."],[0,"(b) Repealed. Pub. L. 88–489, §1, Aug. 26, 1964, 78 Stat. 602."],[0,"(c) The processing and utilization of source, byproduct, and special nuclear material affect interstate and foreign commerce and must be regulated in the national interest."],[0,"(d) The processing and utilization of source, byproduct, and special nuclear material must be regulated in the national interest and in order to provide for the common defense and security and to protect the health and safety of the public."],[0,"(e) Source and special nuclear material, production facilities, and utilization facilities are affected with the public interest, and regulation by the United States of the production and utilization of atomic energy and of the facilities used in connection therewith is necessary in the national interest to assure the common defense and security and to protect the health and safety of the public."],[0,"(f) The necessity for protection against possible interstate damage occurring from the operation of facilities for the production or utilization of source or special nuclear material places the operation of those facilities in interstate commerce for the purposes of this chapter."],[0,"(g) Funds of the United States may be provided for the development and use of atomic energy under conditions which will provide for the common defense and security and promote the general welfare."],[0,"(h) Repealed. Pub. L. 88–489, §2, Aug. 26, 1964, 78 Stat. 602."],[0,"(i) In order to protect the public and to encourage the development of the atomic energy industry, in the interest of the general welfare and of the common defense and security, the United States may make funds available for a portion of the damages suffered by the public from nuclear incidents, and may limit the liability of those persons liable for such losses."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2012. Congressional findings","tname":"The Public Health and Welfare","by":{"1":"15"}},{"t":"usc","label":"42 U.S.C. § 2013","url":"https://www.law.cornell.edu/uscode/text/42/2013","subs":["(d)"],"by":{"1":"2, 12, 31"}},{"t":"usc","label":"42 U.S.C. § 2014","url":"https://www.law.cornell.edu/uscode/text/42/2014","subs":["(e)(1)","(e)(2)","(v)","(z)","(aa)","(cc)"],"by":{"1":"4, 5, 9, 16, 23, 4, 3, 16, 3, 4"}},{"t":"usc","label":"42 U.S.C. § 2018","url":"https://www.law.cornell.edu/uscode/text/42/2018","stext":{"head":"§2018. Agency jurisdiction","paras":[[0,"Nothing in this chapter shall be construed to affect the authority or regulations of any Federal, State, or local agency with respect to the generation, sale, or transmission of electric power produced through the use of nuclear facilities licensed by the Commission: Provided, That this section shall not be deemed to confer upon any Federal, State, or local agency any authority to regulate, control, or restrict any activities of the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2018?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2018. Agency jurisdiction","tname":"The Public Health and Welfare","by":{"1":"2, 15, 20, 25","3":"3, 15, 16"}},{"t":"usc","label":"42 U.S.C. § 2021b","url":"https://www.law.cornell.edu/uscode/text/42/2021b","subs":["(9)(A)(i)"],"by":{"1":"33"}},{"t":"usc","label":"42 U.S.C. § 2022","url":"https://www.law.cornell.edu/uscode/text/42/2022","subs":["(b)(1)"],"by":{"1":"3, 5"}},{"t":"usc","label":"42 U.S.C. § 2023","url":"https://www.law.cornell.edu/uscode/text/42/2023","subs":["(a)"],"by":{"1":"32, 33"}},{"t":"usc","label":"42 U.S.C. § 2073","url":"https://www.law.cornell.edu/uscode/text/42/2073","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 2092","url":"https://www.law.cornell.edu/uscode/text/42/2092","stext":{"head":"§2092. License requirements for transfers","paras":[[0,"Unless authorized by a general or specific license issued by the Commission which the Commission is authorized to issue, no person may transfer or receive in interstate commerce, transfer, deliver, receive possession of or title to, or import into or export from the United States any source material after removal from its place of deposit in nature, except that licenses shall not be required for quantities of source material which, in the opinion of the Commission, are unimportant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2092?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2092. License requirements for transfers","tname":"The Public Health and Welfare","by":{"1":"3, 4","2":"passim, 7"}},{"t":"usc","label":"42 U.S.C. § 2093","url":"https://www.law.cornell.edu/uscode/text/42/2093","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 2099","url":"https://www.law.cornell.edu/uscode/text/42/2099","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 2131","url":"https://www.law.cornell.edu/uscode/text/42/2131","stext":{"head":"§2131. License required","paras":[[0,"It shall be unlawful, except as provided in section 2121 of this title, for any person within the United States to transfer or receive in interstate commerce, manufacture, produce, transfer, acquire, possess, use, import, or export any utilization or production facility except under and in accordance with a license issued by the Commission pursuant to section 2133 or 2134 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2131?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2131. License required","tname":"The Public Health and Welfare","by":{"1":"4"}},{"t":"usc","label":"42 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/42/2201","subs":["(b)"],"by":{"1":"3"}},{"t":"usc","label":"21 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/21/601","by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 5811","url":"https://www.law.cornell.edu/uscode/text/42/5811","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 5841","url":"https://www.law.cornell.edu/uscode/text/42/5841","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 7151","url":"https://www.law.cornell.edu/uscode/text/42/7151","subs":["(a)"],"by":{"1":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"1":"22, 27","2":"13, 37, 45, 47"}},{"t":"reg","label":"34 Fed. Reg. 7273","url":"https://www.govinfo.gov/link/fr/34/7273","by":{"1":"18"}},{"t":"reg","label":"62 Fed. Reg. 46,517","url":"https://www.govinfo.gov/link/fr/62/46517","by":{"1":"32"}},{"t":"reg","label":"77 Fed. Reg. 21,625","url":"https://www.govinfo.gov/link/fr/77/21625","by":{"1":"18"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"2":"24, 25"}},{"t":"case","label":"Armour & Co. v. Wantock","cite":"323 U.S. 126","y":1944,"id":"scdb/1944-014","sc":1,"sum":"1. Fireguards employed by a manufacturer of goods for interstate comnerce, held covered by the Fair Labor Standards Act of 1938, as employed in an \"occupation necessary to the production\" of goods for interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Bonito Boats, Inc. v. Thunder Craft Boats, Inc.","cite":"489 U.S. 141","y":1989,"id":"1988/87-1346","sc":1,"sum":"The Court held that a state statute that contradicts with the public policy behind federal statutes is invalid.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Cipollone v. Liggett Group","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"De Canas v. Bica","cite":"424 U.S. 351","y":1976,"id":"1975/74-882","sc":1,"sum":"Section 2805 (a) of the California Labor Code, which prohibits an employer from knowingly employing an alien who is not entitled to lawful residence in the United States if such employment would have an adverse effect on lawful resident workers, held not to be unconstitutional as a regulation of immigration or as being preempted under the Supremacy Clause by the Immigration and Nationality Act (INA).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14, 20"}},{"t":"case","label":"Edwards v. Aguillard","cite":"482 U.S. 578","y":1987,"id":"1986/85-1513","sc":1,"sum":"The Court held that it was a violation of the Establishment Clause of the First Amendment to mandate the teaching of creation science when teaching evolution science.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Farmer v. Carpenters","cite":"430 U.S. 290","y":1977,"id":"1976/75-804","sc":1,"sum":"A member and officer (petitioner's decedent) of respondent local carpenters' Union brought a tort action for damages in California state court against respondent Unions and Union officials, alleging in count two of the complaint that, because of a sharp disagreement between him and Union officials over various internal Union policies, respondents had intentionally engaged in outrageous conduct, threats, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Federal Maritime Comm’n v. South Carolina State Ports Auth.","cite":"535 U.S. 743","y":2002,"id":"2001/01-46","sc":1,"sum":"The Court held that state sovereign immunity bars the FMC from adjudicating a private party's complaint against a nonconsenting State. Historically, the Court noted, states were not subject to private suits in administrative adjudications when the Constitution was adopted, and states were thus presumptively immune from such actions.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Hans v. Louisiana","cite":"134 U.S. 1","y":1890,"id":"scdb/1889-145","sc":1,"sum":"A State cannot, without its consent, be sued’in a Circuit Court of the United States by one of its own citizens, upon a suggestion that the case is one that arises under the Constitution and laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Haywood v. Drown","cite":"556 U.S. 729","y":2009,"id":"2008/07-10374","sc":1,"sum":"The Court found that prohibiting civil claims against correction officers in their official capacities violated the Supremacy Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Hodel v. Virginia Surface Mining & Reclamation Ass’n","cite":"452 U.S. 264","y":1981,"id":"1980/79-1538","sc":1,"sum":"In the context of a facial challenge, the Act is constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Hunter v. Underwood","cite":"471 U.S. 222","y":1985,"id":"1984/84-76","sc":1,"sum":"Section 182 violates the Equal Protection Clause of the Fourteenth Amendment. Arlington Heights v. MetropolitanHousingDevelopment Corp., 429 U. S. 252. That § 182 may have been adopted to discriminate against poor whites as well as against blacks would not render nugatory the purpose to discriminate against blacks, it being clear that the latter was a \"but-for\" motivation for adopting § 182. There is no evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Kindred Nursing Ctrs. Ltd. P’ship v. Clark","cite":"137 S. Ct. 1421","y":2017,"id":"2016/16-32","sc":1,"sum":"The Court held that the Federal Arbitration Act (FAA) preempts Kentucky state-law precedent that requires a clear statement in the power of attorney agreement in order to grant an attorney-in-fact the power to bind her principal to an arbitration agreement.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Lewis v. Jeffers","cite":"497 U.S. 764","y":1990,"id":"1989/89-189","sc":1,"sum":"The Court held that federal habeas corpus relief is not intended to find error in state laws but rather to determine whether a state court’s finding was so arbitrary and capricious that it violates the Eighth Amendment.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Massachusetts v. United States","cite":"333 U.S. 611","y":1948,"id":"scdb/1947-065","sc":1,"sum":"1. Under R. S. § 3466, the United States has priority for payment from an insolvent debtor's estate of federal insurance contribution taxes under Title 8 and unemployment compensation taxes under Title 9 of the Social Security Act, as against a state's claim for unemployment compensation taxes imposed by a state statute conforming to the' federal act's requirements, Illinois v. United States, 328 U. S.8; Illinois v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Medtronic, Inc. v. Lohn","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Murphy v. National Collegiate Athletic Ass’n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"2":"19, 21"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"2":"52","3":"25"}},{"t":"case","label":"Northern Nat’l Gas Co. v. State Corp. Comm’n of Kansas","cite":"372 U.S. 84","y":1963,"id":"1962/62","sc":1,"sum":"Orders of the Kansas State Corporation Commission which require appellant, an interstate pipeline company, to purchase natural gas ratably from all wells connecting with its pipeline system in each gas field in the State held invalid, because they invade the exclusive jurisdiction which the Natural Gas Act has conferred upon the Federal Power Commission over the sale and transportation of natural gas in interstate …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"135 S. Ct. 1591","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"2":"19, 20, 49"}},{"t":"case","label":"Pacific Gas & Elec. Co. v. State Energy Res. Conservation & Dev. Comm’n","cite":"489 F. Supp. 699","y":1980,"court":"E.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./489/699/","by":{"2":"35"}},{"t":"case","label":"Pacific Legal Found. v. State Energy Res. Conservation & Dev. Comm’n","cite":"659 F.2d 903","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/659/903/","by":{"2":"35"}},{"t":"case","label":"Palmer v. Thompson","cite":"403 U.S. 217","y":1971,"id":"1970/107","sc":1,"sum":"Following the Court of Appeals' affirmance of a District Court judgment invalidating enforced segregation on equal protection grounds, the city council of Jackson, Mississippi, desegregated its public recreational facilities, including its five public parks, except for their swimming pools. Stating that the pools could not be operated safely and economically on an integrated basis, the council closed four city-owned …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Peña-Rodriguez v. Colorado","cite":"137 S. Ct. 855","y":2017,"id":"2016/15-606","sc":1,"sum":"The Court held that the no-impeachment rule may not bar evidence of racial bias offered to prove a violation of the Sixth Amendment right to an impartial jury.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Power Reactor Dev. Co. v. International Union of Elec., Radio & Mach. Workers","cite":"367 U.S. 396","y":1961,"id":"1960/315","sc":1,"sum":"The Court of Appeals erred in setting aside the Commission's order continuing the provisional construction permit in effect.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"2":"52"}},{"t":"case","label":"Puerto Rico Dep’t of Consumer Affairs v. Isla Petroleum Corp.","cite":"485 U.S. 495","y":1988,"id":"1987/86-1406","sc":1,"sum":"The Department's regulations are not pre-empted. The test for federal pre-emption of Puerto Rico law is the same as the test under the Supremacy Clause for pre-emption of the law of a State. There is no merit to respondents' contention that the EPAA evinced a federal intent to enter the field of petroleum allocation and price regulation, and that the EPCA never countermanded that intent, but merely changed the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim","3":"9, 10, 11"}},{"t":"case","label":"Shady Grove Orthopedic Associates, P.A. v. Allstate Insurance Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"ar":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"2":"passim","3":"11, 12, 13"}},{"t":"case","label":"Shelley v. Kraemer","cite":"334 U.S. 1","y":1948,"id":"1940-1955/334us1","sc":1,"sum":"The Court ruled that enforcement of racially restrictive covenants were a violation of the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Southern Pac. Co. v. Jensson","cite":"244 U.S. 205","y":1917,"id":"scdb/1916-076","sc":1,"sum":"The Federal Employers’ Liability Act applies only wherethe injury occurs in railroad operations or their adjuncts, and cannot be extended to interstate maritime transportation merely because the vessel in the case is owned and operated by an interstate carrier by railroad.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"2":"15, 39"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Res. Def. Council","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Virginia v. Black","cite":"538 U.S. 343","y":2003,"id":"2002/01-1107","sc":1,"sum":"The Court held that a law banning cross-burning with the intent to intimidate is constitutional. However, cross burning is not prima facie evidence of intent to intimidate.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"West Va. Univ. Hosps. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38, 50"}},{"t":"case","label":"Wisconsin Pub. Intervenor v. Mortier","cite":"501 U.S. 597","y":1991,"id":"1990/89-1905","sc":1,"sum":"FIFRA does not pre-empt local governmental regulation of pesticide use.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":2,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"2":"19, 21, 50"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"2":"24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"2":"4"}},{"t":"usc","label":"33 U.S.C. § 1313","url":"https://www.law.cornell.edu/uscode/text/33/1313","by":{"2":"52"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","by":{"2":"52"}},{"t":"usc","label":"42 U.S.C. § 2095","url":"https://www.law.cornell.edu/uscode/text/42/2095","stext":{"head":"§2095. Reports","paras":[[0,"The Commission is authorized to issue such rules, regulations, or orders requiring reports of ownership, possession, extraction, refining, shipment, or other handling of source material as it may deem necessary, except that such reports shall not be required with respect to (a) any source material prior to removal from its place of deposit in nature, or (b) quantities of source material which in the opinion of the Commission are unimportant or the reporting of which will discourage independent prospecting for new deposits."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2095?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2095. Reports","tname":"The Public Health and Welfare","by":{"2":"7, 7"}},{"t":"usc","label":"42 U.S.C. § 2096","url":"https://www.law.cornell.edu/uscode/text/42/2096","subs":["(a)","(b)","(c)"],"stext":{"head":"§2096. Acquisition of source material; payments","paras":[[0,"The Commission is authorized and directed, to the extent it deems necessary to effectuate the provisions of this chapter—"],[1,"(a) to purchase, take, requisition, condemn, or otherwise acquire supplies of source material;"],[1,"(b) to purchase, condemn, or otherwise acquire any interest in real property containing deposits of source material; and"],[1,"(c) to purchase, condemn, or otherwise acquire rights to enter upon any real property deemed by the Commission to have possibilities of containing deposits of source material in order to conduct prospecting and exploratory operations for such deposits."],[0,"Any purchase made under this section may be made without regard to the provisions of section 6101 of title 41, upon certification by the Commission that such action is necessary in the interest of the common defense and security, or upon a showing by the Commission that advertising is not reasonably practicable. Partial and advanced payments may be made under contracts for such purposes. The Commission may establish guaranteed prices for all source material delivered to it within a specified time. Just compensation shall be made for any right, property, or interest in property taken, requisitioned, condemned, or otherwise acquired under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2096?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2096. Acquisition of source material; payments","tname":"The Public Health and Welfare","by":{"2":"15, 15, 15, 7"}},{"t":"law","label":"Pub. L. No. 83-703","url":"https://www.govinfo.gov/link/statute/68/919","by":{"2":"6"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"2":"50"}},{"t":"case","label":"Alabama v. Shelton","cite":"535 U.S. 654","y":2002,"id":"2001/00-1214","sc":1,"sum":"The Court held, according to Argersinger, that a suspended sentence that may \"end up in the actual deprivation of a person's liberty\" may not be imposed unless the defendant was accorded \"the guiding hand of counsel\" in the prosecution for the crime charged.","sumSrc":"Oyez","by":{"3":"17, 23"}},{"t":"case","label":"Employment Div. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"134 S. Ct. 1584","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/1584/","sc":1,"by":{"3":"12"}},{"t":"case","label":"Gonzales v. O Centro Espirita Beneficente Uniao do Vegetal","cite":"546 U.S. 418","y":2006,"id":"2005/04-1084","sc":1,"sum":"In a unanimous 8-0 decision (Justice Alito not participating), the Court held that the government had failed to prove a compelling interest in regulating the UDV's use of drugs for religious purposes. Writing for the Court, Chief Justice John Roberts rejected the government's argument that the Controlled Substances Act could accommodate no exceptions.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Hunt v. Cromartie","cite":"526 U.S. 541","y":1999,"id":"1998/98-85","sc":1,"sum":"The Court held that despite strong evidence of racial gerrymandering, the North Carolina General Assembly's motivations were in dispute. As such, further inquiry was warranted on this alone. Moreover, since accusations of racial gerrymandering rise to the level of being constitutionally significant, they must be evaluated with strict scrutiny.","sumSrc":"Oyez","by":{"3":"12, 23"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Maine v. Taylor","cite":"477 U.S. 131","y":1986,"id":"1985/85-62","sc":1,"sum":"In an 8-to-1 decision, the Court held that the limitation imposed by the Commerce Clause on state regulatory power was not absolute and that the States \"retain[ed] authority under their general police powers to regulate matters of 'legitimate local concern.'\" The Court found that Maine's ban on the importation oflive baitfish served a legitimate local purpose that could not adequately be served by available nondiscriminatory alternatives.","sumSrc":"Oyez","by":{"3":"12, 23"}},{"t":"case","label":"Maryland Comm. for Fair Representation v. Tawes","cite":"377 U.S. 656","y":1964,"id":"1963/29","sc":1,"sum":"The Court held that neither house of the Maryland Legislature is apportioned sufficiently on a population basis to be constitutionally sustainable, based on the Court's ruling in Reynolds v. Sims, 377 U.S. 533 (1964).","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"McLane Co., Inc. v. EEOC","cite":"137 S. Ct. 1159","y":2017,"id":"2016/15-1248","sc":1,"sum":"A case in which the Court will decide whether a district court’s decision to enforce an Equal Employment Opportunity Commission subpoena should be reviewed “de novo,” or without deference to the lower court’s determination.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"134 S. Ct. 2024","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"3":"4, 17"}}]};